import{_ as d,o as e,c as r,a3 as o}from"./chunks/framework.DVCfY5-a.js";const A=JSON.parse('{"title":"API 配置","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/config","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),_={name:"reference/config.md"};function c(a,t,T,E,S,n){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h1><p>Node 配置直接来自运行服务的解析器。使用方法见 <a href="./../guides/server-platform">平台指南</a>。生产秘密不进入文档。</p><h2 id="当前-lab-world-server" tabindex="-1">当前 Lab World Server <a class="header-anchor" href="#当前-lab-world-server" aria-label="Permalink to &quot;当前 Lab World Server&quot;">​</a></h2><p>默认值由 <a href="https://github.com/CaiZongyuan/labworld/blob/bb30302126c39bfac561ae63dc395c2bf2195b1b/apps/server/src/config.ts" target="_blank" rel="noreferrer">config.ts</a> 的实际解析器生成。Web 的 <code>WEB_PORT</code> 和 <code>VITE_API_PROXY</code> 由开发入口和 Vite 读取。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>敏感值</th><th>说明</th></tr></thead><tbody><tr><td><code>LAB_WORD_NEWTON_SESSION</code></td><td>false</td><td>否</td><td>启用固定 Newton 会话；本地监管还需 Linux/WSL、固定 Python 和场景输入。</td></tr><tr><td><code>LAB_WORD_NEWTON_PYTHON</code></td><td></td><td>否</td><td>仅显式 Newton Start 使用的固定 Python 环境。</td></tr><tr><td><code>LAB_WORD_NEWTON_SCENE_DIRECTORY</code></td><td></td><td>否</td><td>包含已校验基础 GLB 的固定场景目录。</td></tr><tr><td><code>LAB_WORD_NEWTON_PUBLISHER</code></td><td></td><td>否</td><td>可选 Newton Publisher 绝对路径；默认使用随服务提供的来源。</td></tr><tr><td><code>LAB_WORD_TLS_CERT</code></td><td></td><td>否</td><td>单个 HTTPS/WSS 监听器的可选 PEM 证书链；需要 TLS 密钥和 HTTPS APP_ORIGIN。</td></tr><tr><td><code>LAB_WORD_TLS_KEY</code></td><td></td><td>否</td><td>与 LAB_WORD_TLS_CERT 配对的可选 PEM 私钥路径；限制文件读取权限。</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_MANAGED</code></td><td>false</td><td>否</td><td>监管本机 Synthetic 子进程；空值沿用合成会话开关。外部机器来源设为 false。</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_SESSION</code></td><td>false</td><td>否</td><td>启用带可靠录制的 Synthetic 会话；需要回环明文或已配置的 TLS。</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_PYTHON</code></td><td>python3</td><td>否</td><td>仅在显式 Start 开发合成会话时使用的 Python 可执行文件。</td></tr><tr><td><code>LAB_WORD_SYNTHETIC_PUBLISHER</code></td><td></td><td>否</td><td>可选 publisher.py 绝对路径；默认使用随服务提供的开发来源。</td></tr><tr><td><code>LAB_WORD_MOTION_GRACE_MS</code></td><td>5000</td><td>否</td><td>Publisher 心跳和来源进度宽限毫秒数，1000–60000。</td></tr><tr><td><code>LAB_WORD_MOTION_ACK_MS</code></td><td>3000</td><td>否</td><td>来源生命周期确认期限毫秒数，1000–60000。</td></tr><tr><td><code>LAB_WORD_MOTION_FIXTURE</code></td><td>false</td><td>否</td><td>启用经过认证的合成运动测试 fixture；必须监听 loopback。</td></tr><tr><td><code>LAB_WORD_WEB_DIR</code></td><td></td><td>否</td><td>生产同源托管的 Web 构建目录；空值关闭静态托管。</td></tr><tr><td><code>LAB_WORD_HOST</code></td><td>127.0.0.1</td><td>否</td><td>监听主机；兼容回退为 APP_BIND。</td></tr><tr><td><code>SERVER_PORT</code></td><td>3000</td><td>否</td><td>监听端口，整数 1–65535。</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>可信 Web origin；HTTPS 或回环 HTTP。</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>否</td><td>会话绝对有效期秒数，60–2592000。</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>否</td><td>会话空闲有效期秒数，60 至绝对有效期。</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td>true</td><td>否</td><td>启用进程内限流，true 或 false。</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td>60</td><td>否</td><td>整数 1–3600；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td>4096</td><td>否</td><td>整数 1–100000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td>20</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td>5</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td>60</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td>20</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td>600</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td>120</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>否</td><td>整数 1–104857600；流式字节上限。</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>否</td><td>整数 1–3600；capability 有效期秒数。</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>否</td><td>整数 1–300；capability 有效期秒数。</td></tr><tr><td><code>FILE_PUBLIC_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>字节 URL 的 origin；默认使用可信 Web origin，HTTPS 或回环 HTTP。</td></tr><tr><td><code>LAB_OBSERVATION_RETENTION_SECS</code></td><td>86400</td><td>否</td><td>原始观测保留秒数（1–31536000）；保留当前属性。</td></tr><tr><td><code>LAB_RECORD_RETENTION_SECS</code></td><td>2592000</td><td>否</td><td>结束记录保留秒数（1–31536000）；保留在途 Task。</td></tr><tr><td><code>LAB_WORD_DATA_DIR</code></td><td>data</td><td>否</td><td>拥有的持久数据库、字节与密钥目录；测试回退为 CONTRACT_DATA_DIRECTORY。</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/bb30302126c39bfac561ae63dc395c2bf2195b1b/.env.example" target="_blank" rel="noreferrer">.env.example</a>展示当前 Node 与 Web 配置；普通服务不读取旧数据库、Redis 或对象存储设置。服务与 Web 的启动见 <a href="./../guides/server-foundation">TypeScript 服务基础</a>。</p>',6)])])}const R=d(_,[["render",c]]);export{A as __pageData,R as default};
